-- ----------------------------------------------
-- LOAN_ACCOUNT
-- ----------------------------------------------
DROP TABLE IF EXISTS loan_account;
CREATE TABLE loan_account (
    loan_id TEXT,
    cif TEXT,
    loan_type TEXT,
    principal_amount NUMERIC(24,6),
    remaining_balance NUMERIC(24,6),
    start_date DATE,
    end_date DATE,
    interest_rate NUMERIC(24,6),
    status TEXT,
    branch_id TEXT,
    department_id TEXT,
    portfolio_id TEXT,
    source_system TEXT,
    PRIMARY KEY (loan_id)
);
CREATE INDEX idx_loan_account_cif ON loan_account(cif);
COMMIT;
